1	// Shared assertions, messages and fixtures for the server/API test files.
2	import { before, after } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { makeTempDir, removeDir, startServer, request, validBooking, JSON_TYPE } from './server-harness.mjs';
5	
6	/** The booking reply's keys, sorted. */
7	export const SIX_KEYS = Object.freeze(['date', 'end', 'id', 'room', 'start', 'title']);
8	export const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
9	
10	/** Every error message the spec names, verbatim. */
11	export const MSG = Object.freeze({
12	  type: 'content type must be application/json',
13	  size: 'body too large',
14	  object: 'body must be a JSON object',
15	  room: 'room must be one of Aurora, Borealis, Cosmos',
16	  title: 'title must be 1 to 80 characters',
17	  date: 'date must be a valid YYYY-MM-DD date',
18	  start: 'start must be HH:MM',
19	  end: 'end must be HH:MM',
20	  order: 'end must be after start',
21	  bookingNotFound: 'booking not found',
22	  notFound: 'not found',
23	  method: 'method not allowed',
24	  internal: 'internal error',
25	});
26	
27	/** Exact JSON error reply: status, Content-Type and a body with only the `error` key. */
28	export function assertJsonError(res, status, message) {
29	  assert.equal(res.status, status);
30	  assert.equal(res.headers['content-type'], JSON_TYPE);
31	  assert.deepEqual(res.json(), { error: message });
32	}
33	
34	/** Exact 201 reply: Content-Type, exactly the six keys, numeric id, and `expected` fields. Returns the booking. */
35	export function assertCreated(res, expected) {
36	  assert.equal(res.status, 201);
37	  assert.equal(res.headers['content-type'], JSON_TYPE);
38	  const body = res.json();
39	  assert.deepEqual(Object.keys(body).sort(), SIX_KEYS);
40	  assert.equal(typeof body.id, 'number');
41	  assert.deepEqual(body, { id: body.id, ...expected });
42	  return body;
43	}
44	
45	/** GET /api/bookings (optional query string) and return the bookings array, asserting a 200 JSON reply. */
46	export async function listBookings(port, query = '') {
47	  const res = await request(port, { path: `/api/bookings${query}` });
48	  assert.equal(res.status, 200);
49	  assert.equal(res.headers['content-type'], JSON_TYPE);
50	  return res.json().bookings;
51	}
52	
53	let dayCounter = 0;
54	/** A date (2030 onwards) no other test in this process has used. */
55	export function freshDate() {
56	  dayCounter += 1;
57	  return new Date(Date.UTC(2030, 0, 1 + dayCounter)).toISOString().slice(0, 10);
58	}
59	
60	/** A valid booking body on a fresh date. */
61	export function freshBooking(overrides = {}) {
62	  return validBooking({ date: freshDate(), ...overrides });
63	}
64	
65	/** A readable, unique-ish test label for a value: invisible characters are shown as \uXXXX escapes. */
66	export function label(value) {
67	  if (value === undefined) return '<missing>';
68	  return JSON.stringify(value).replace(/[^\x20-\x7e]/gu, (ch) => `\\u{${ch.codePointAt(0).toString(16)}}`);
69	}
70	
71	/**
72	 * Registers before/after hooks in the current describe that start one server
73	 * (cwd = temp dir, DATA_FILE='data.json') and stop it. Returns a context whose
74	 * `port`, `server` and `dir` are set once the before hook ran.
75	 */
76	export function useServer() {
77	  const ctx = {};
78	  before(async () => {
79	    ctx.dir = await makeTempDir();
80	    ctx.server = await startServer({ cwd: ctx.dir, env: { DATA_FILE: 'data.json' } });
81	    ctx.port = ctx.server.port;
82	  });
83	  after(async () => {
84	    if (ctx.server) await ctx.server.stop();
85	    if (ctx.dir) await removeDir(ctx.dir);
86	  });
87	  return ctx;
88	}
89	
90	/** Runs fn(dir) in a fresh temp dir and always removes it. */
91	export async function withTempDir(fn) {
92	  const dir = await makeTempDir();
93	  try {
94	    return await fn(dir);
95	  } finally {
96	    await removeDir(dir);
97	  }
98	}
99	
100	/** Starts a server with `options`, runs fn(server) and always stops it. */
101	export async function withServer(options, fn) {
102	  const server = await startServer(options);
103	  try {
104	    return await fn(server);
105	  } finally {
106	    await server.stop();
107	  }
108	}
