1	// Booking rules 1-5 (content type, size, JSON object, room, title), rule order and id handling.
2	import { describe, it, before, after } from 'node:test';
3	import assert from 'node:assert/strict';
4	import {
5	  startServer, request, postBooking, validBooking, JSON_TYPE, makeTempDir, removeDir,
6	} from './helpers/server-harness.mjs';
7	
8	const SIX_KEYS = ['date', 'end', 'id', 'room', 'start', 'title'];
9	const MSG = {
10	  type: 'content type must be application/json',
11	  size: 'body too large',
12	  object: 'body must be a JSON object',
13	  room: 'room must be one of Aurora, Borealis, Cosmos',
14	  title: 'title must be 1 to 80 characters',
15	  date: 'date must be a valid YYYY-MM-DD date',
16	  start: 'start must be HH:MM',
17	  end: 'end must be HH:MM',
18	  order: 'end must be after start',
19	};
