21	let dayCounter = 0;
22	function freshDate() {
23	  dayCounter += 1;
24	  return new Date(Date.UTC(2030, 0, 1 + dayCounter)).toISOString().slice(0, 10);
25	}
26	
27	/** A valid booking on a date no other test uses; `undefined` overrides drop the key. */
28	function booking(overrides = {}) {
29	  return validBooking({ date: freshDate(), ...overrides });
30	}
