32	/** POST without defaults: contentType undefined really sends no Content-Type header. */
33	function postWith(port, value, contentType, raw = false) {
34	  const body = raw ? value : JSON.stringify(value);
35	  const headers = contentType === undefined ? {} : { 'Content-Type': contentType };
36	  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
37	}
38	
39	function label(value) {
40	  return value === undefined ? '<missing>' : JSON.stringify(value);
41	}
