43	function useServer() {
44	  const ctx = {};
45	  before(async () => {
46	    ctx.dir = await makeTempDir();
47	    ctx.server = await startServer({ cwd: ctx.dir, env: { DATA_FILE: 'data.json' } });
48	    ctx.port = ctx.server.port;
49	  });
50	  after(async () => {
51	    if (ctx.server) await ctx.server.stop();
52	    if (ctx.dir) await removeDir(ctx.dir);
53	  });
