63	function assertCreated(res, expected) {
64	  assert.equal(res.status, 201);
65	  assert.equal(res.headers['content-type'], JSON_TYPE);
66	  const body = res.json();
67	  assert.deepEqual(Object.keys(body).sort(), SIX_KEYS);
68	  assert.equal(typeof body.id, 'number');
69	  assert.deepEqual(body, { id: body.id, ...expected });
70	  return body;
71	}
