73	/** Bytes of `obj` as JSON padded with spaces inside the object to exactly `size` bytes. */
74	function paddedBody(obj, size) {
75	  const json = JSON.stringify(obj);
76	  const pad = size - Buffer.byteLength(json);
77	  assert.ok(pad >= 0);
78	  const text = '{' + ' '.repeat(pad) + json.slice(1);
79	  assert.equal(Buffer.byteLength(text), size);
80	  return Buffer.from(text);
81	}
82	
83	/** Body with an ignored "pad" key of 'é' (2 bytes each) plus spaces, exactly `size` bytes. */
84	function accentBody(obj, size) {
85	  const base = Buffer.byteLength(JSON.stringify({ ...obj, pad: '' }));
86	  const count = Math.floor((size - base) / 2);
87	  const text = JSON.stringify({ ...obj, pad: 'é'.repeat(count) });
88	  const full = ' '.repeat(size - Buffer.byteLength(text)) + text;
89	  assert.equal(Buffer.byteLength(full), size);
90	  return { buffer: Buffer.from(full), text: full };
91	}
92	
93	function chunked(buffer, chunkSize = 1000) {
94	  const chunks = [];
95	  for (let i = 0; i < buffer.length; i += chunkSize) chunks.push(buffer.subarray(i, i + chunkSize));
96	  return chunks;
97	}
