99	describe('rule order ladder', () => {
100	  const ctx = useServer();
101	  const ok = { room: 'Aurora', title: 'ok', date: '2030-12-01', start: '09:00', end: '10:00' };
102	  const bad = 'x';
103	  const rawCases = [
104	    ['no content type, 20000 bytes', undefined, Buffer.alloc(20000, 'x'), 415, MSG.type],
105	    ['text/plain, 20000 bytes', 'text/plain', Buffer.alloc(20000, 'x'), 415, MSG.type],
106	    ['json, 10001 bytes invalid', 'application/json', Buffer.alloc(10001, 'x'), 413, MSG.size],
107	    ['json, "[1"', 'application/json', '[1', 400, MSG.object],
108	  ];
109	  for (const [name, contentType, body, status, message] of rawCases) {
110	    it(name, async () => {
111	      assertJsonError(await postWith(ctx.port, body, contentType, true), status, message);
112	    });
113	  }
114	
115	  const fieldCases = [
116	    ['room first', { room: bad, title: '', date: bad, start: bad, end: bad }, MSG.room],
117	    ['title next', { ...ok, title: '', date: bad, start: bad, end: bad }, MSG.title],
118	    ['date next', { ...ok, date: bad, start: bad, end: bad }, MSG.date],
119	    ['start next', { ...ok, start: bad, end: bad }, MSG.start],
120	    ['end next', { ...ok, end: bad }, MSG.end],
121	  ];
122	  for (const [name, body, message] of fieldCases) {
123	    it(name, async () => assertJsonError(await postBooking(ctx.port, body), 400, message));
124	  }
125	
126	  it('end before start beats an overlap (400, not 409)', async () => {
127	    assertCreated(await postBooking(ctx.port, ok), ok);
128	    const res = await postBooking(ctx.port, { ...ok, start: '10:00', end: '09:00' });
129	    assertJsonError(res, 400, MSG.order);
130	  });
131	});
