133	describe('rule 1 content type', () => {
134	  const ctx = useServer();
135	  const rejected = [
136	    undefined, '', 'text/plain', 'application/jsonx', 'application/json-patch+json',
137	    'application/x-json', 'json', 'application/json, text/plain', 'application/ json', 'text/json',
138	  ];
139	  for (const contentType of rejected) {
140	    it(`rejects ${label(contentType)}`, async () => {
141	      const res = await postWith(ctx.port, booking(), contentType);
142	      assertJsonError(res, 415, MSG.type);
143	    });
144	  }
145	  const accepted = [
146	    'application/json', 'Application/JSON ; charset=x', 'APPLICATION/JSON',
147	    'application/json;charset=utf-8', 'application/json;', 'application/json\t;x',
148	    ' application/json', '\tapplication/json\t',
149	  ];
150	  for (const contentType of accepted) {
151	    it(`accepts ${label(contentType)}`, async () => {
152	      const value = booking();
153	      assertCreated(await postBooking(ctx.port, value, { contentType }), value);
154	    });
155	  }
156	});
