158	describe('rule 2 body size', () => {
159	  const ctx = useServer();
160	  const post = (body) => postBooking(ctx.port, body, { raw: true });
161	  function check(res, status, value) {
162	    if (status === 201) assertCreated(res, value);
163	    else assertJsonError(res, 413, MSG.size);
164	  }
165	  const sized = [[10000, 201], [10001, 413]];
166	  for (const [size, status] of sized) {
167	    it(`space padded body of ${size} bytes`, async () => {
168	      const value = booking();
169	      const body = paddedBody(value, size);
170	      assert.equal(body.length, size);
171	      check(await post(body), status, value);
172	    });
173	    it(`multi-byte padded body of ${size} bytes`, async () => {
174	      const value = booking();
175	      const { buffer, text } = accentBody(value, size);
176	      assert.equal(Buffer.byteLength(text), size);
177	      assert.ok(text.length < 10000);
178	      check(await post(buffer), status, value);
179	    });
180	    it(`chunked body of ${size} bytes`, async () => {
181	      const value = booking();
182	      const chunks = chunked(paddedBody(value, size));
183	      assert.equal(chunks.reduce((n, c) => n + c.length, 0), size);
184	      check(await post(chunks), status, value);
185	    });
186	  }
187	});
