189	describe('rule 3 body must be a JSON object', () => {
190	  const ctx = useServer();
191	  const notObjects = ['', ' ', 'not json', 'null', '[]', '[{}]', '"str"', '1', 'true', 'false', '{', '{"room":"Aurora",}'];
192	  for (const text of notObjects) {
193	    it(`rejects ${JSON.stringify(text)}`, async () => {
194	      assertJsonError(await postBooking(ctx.port, text, { raw: true }), 400, MSG.object);
195	    });
196	  }
197	
198	  it('rejects a body with a byte order mark', async () => {
199	    const bom = Buffer.from([0xef, 0xbb, 0xbf]);
200	    const body = Buffer.concat([bom, Buffer.from(JSON.stringify(booking()))]);
201	    assertJsonError(await postBooking(ctx.port, body, { raw: true }), 400, MSG.object);
202	  });
203	
204	  it('turns invalid UTF-8 inside a string into U+FFFD', async () => {
205	    const value = booking();
206	    const head = JSON.stringify({ ...value, title: 'A_B' }).split('A_B');
207	    const body = Buffer.concat([Buffer.from(head[0] + 'A'), Buffer.from([0xff]), Buffer.from('B' + head[1])]);
208	    assertCreated(await postBooking(ctx.port, body, { raw: true }), { ...value, title: 'A�B' });
209	  });
210	
211	  it('accepts surrounding whitespace and newlines', async () => {
212	    const value = booking();
213	    const body = ' \n\t\r\n' + JSON.stringify(value) + '\n \r\n';
214	    assertCreated(await postBooking(ctx.port, body, { raw: true }), value);
215	  });
216	
217	  it('ignores extra keys and assigns its own id', async () => {
218	    const value = booking();
219	    const res = await postBooking(ctx.port, { ...value, id: 99, extra: 'x', nextId: 5 });
220	    const created = assertCreated(res, value);
221	    assert.notEqual(created.id, 99);
222	  });
223	});
