225	describe('rule 4 room', () => {
226	  const ctx = useServer();
227	  const rejected = ['aurora', 'AURORA', ' Aurora', 'Aurora ', 'Dune', '', undefined, null, 1, ['Aurora'], {}];
228	  for (const room of rejected) {
229	    it(`rejects ${label(room)}`, async () => {
230	      assertJsonError(await postBooking(ctx.port, booking({ room })), 400, MSG.room);
231	    });
232	  }
233	  for (const room of ['Aurora', 'Borealis', 'Cosmos']) {
234	    it(`accepts ${room}`, async () => {
235	      const value = booking({ room });
236	      assertCreated(await postBooking(ctx.port, value), value);
237	    });
238	  }
239	});
