241	describe('rule 5 title', () => {
242	  const ctx = useServer();
243	  const rejected = [
244	    undefined, null, 5, true, [], '', ' ', '   \t\n ', ' ', '　﻿',
245	    'a'.repeat(81), '😀'.repeat(40) + 'a',
246	  ];
247	  for (const title of rejected) {
248	    it(`rejects ${label(title).slice(0, 30)}`, async () => {
249	      assertJsonError(await postBooking(ctx.port, booking({ title })), 400, MSG.title);
250	    });
251	  }
252	
253	  const accepted = [
254	    ['a'.repeat(80), 'a'.repeat(80)],
255	    ['  ' + 'a'.repeat(80) + '\t\n', 'a'.repeat(80)],
256	    [' x ', 'x'],
257	    [' x ', 'x'],
258	    [' x ', 'x'],
259	    ['😀'.repeat(40), '😀'.repeat(40)],
260	    ['​', '​'],
261	    ['<b>x</b>', '<b>x</b>'],
262	    ['a  b', 'a  b'],
263	  ];
264	  for (const [title, stored] of accepted) {
265	    it(`accepts ${label(title).slice(0, 30)}`, async () => {
266	      const value = booking({ title });
267	      const created = assertCreated(await postBooking(ctx.port, value), { ...value, title: stored });
268	      const list = await request(ctx.port, { path: `/api/bookings?date=${value.date}` });
269	      assert.deepEqual(list.json(), { bookings: [created] });
270	    });
271	  }
272	});
