274	describe('failed POSTs do not consume ids', () => {
275	  const ctx = useServer();
276	  it('next valid booking gets last id + 1', async () => {
277	    const first = booking();
278	    const last = assertCreated(await postBooking(ctx.port, first), first);
279	    const failing = [
280	      () => postBooking(ctx.port, booking(), { contentType: 'text/plain' }),
281	      () => postBooking(ctx.port, Buffer.alloc(10001, ' '), { raw: true }),
282	      () => postBooking(ctx.port, '[1', { raw: true }),
283	      () => postBooking(ctx.port, booking({ room: 'x' })),
284	      () => postBooking(ctx.port, first),
285	    ];
286	    const statuses = [];
287	    for (const send of failing) statuses.push((await send()).status);
288	    assert.deepEqual(statuses, [415, 413, 400, 400, 409]);
289	    const next = booking();
290	    const created = assertCreated(await postBooking(ctx.port, next), next);
291	    assert.equal(created.id, last.id + 1);
292	  });
293	});
