90	describe('rules 7 and 8 start and end', () => {
91	  const ctx = useServer();
92	  const pairs = [['00:00', '00:01'], ['23:58', '23:59'], ['00:00', '23:59']];
93	  for (const [start, end] of pairs) {
94	    it(`accepts ${start}-${end}`, async () => {
95	      const value = booking({ start, end });
96	      assertCreated(await postBooking(ctx.port, value), value);
97	    });
98	  }
99	  const badTimes = [
100	    '24:00', '12:60', '9:00', '09:0', '09:00 ', ' 09:00', '0900', '09:00:00', '09-00',
101	    '-1:00', '٠٩:٠٠', '', 900, null, undefined,
102	  ];
103	  for (const bad of badTimes) {
104	    it(`rejects start ${label(bad)}`, async () => {
105	      const res = await postBooking(ctx.port, booking({ start: bad, end: '23:59' }));
