119	describe('rule 9 end after start', () => {
120	  const ctx = useServer();
121	  const cases = [['09:00', '09:00'], ['10:00', '09:00'], ['23:59', '00:00'], ['00:01', '00:00']];
122	  for (const [start, end] of cases) {
123	    it(`rejects ${start}-${end}`, async () => {
